function getCybereasonTranslation(key, lang) {
    return (cybereasonTranslations[lang] && cybereasonTranslations[lang][key]) ||
           (cybereasonTranslations.en && cybereasonTranslations.en[key]) || null;
}

function applyCybereasonTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.cybereason.") || key.startsWith("review.common."))) {
            const translation = getCybereasonTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} cybereason translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyCybereasonTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyCybereasonTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyCybereasonTranslations(window.i18n?.getCurrentLanguage() || "en");
}
